-- Gate decisions (CONTEXT_PACK §4.2, §4.3, F13). Generated by `pnpm db:generate --name gate_decisions` from
-- src/schema/gate-decisions.ts, then reviewed. Forward-only: never edit once applied; add a new migration.
CREATE TABLE "gate_decisions" (
	"decision_id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"run_id" uuid NOT NULL,
	"gate" integer NOT NULL,
	"kind" text NOT NULL,
	"dedupe_key" text NOT NULL,
	"subtask_id" text,
	"session_id" text,
	"tool_use_id" text,
	"summary" text NOT NULL,
	"target" text,
	"status" text DEFAULT 'pending' NOT NULL,
	"requested_at" timestamp with time zone NOT NULL,
	"timeout_at" timestamp with time zone NOT NULL,
	"decided_by" uuid,
	"decided_at" timestamp with time zone,
	"reason" text,
	"auto" boolean DEFAULT false NOT NULL,
	CONSTRAINT "gate_decisions_tenant_dedupe_key" UNIQUE("tenant_id","dedupe_key"),
	CONSTRAINT "gate_decisions_gate_check" CHECK ("gate_decisions"."gate" BETWEEN 1 AND 3),
	CONSTRAINT "gate_decisions_kind_check" CHECK ("gate_decisions"."kind" IN ('tool_deferred', 'scope_exception')),
	CONSTRAINT "gate_decisions_status_check" CHECK ("gate_decisions"."status" IN ('pending', 'approved', 'denied')),
	CONSTRAINT "gate_decisions_decided_check" CHECK (("gate_decisions"."status" = 'pending' AND "gate_decisions"."decided_at" IS NULL AND "gate_decisions"."decided_by" IS NULL AND "gate_decisions"."auto" = false)
        OR ("gate_decisions"."status" <> 'pending' AND "gate_decisions"."decided_at" IS NOT NULL AND ("gate_decisions"."decided_by" IS NOT NULL OR "gate_decisions"."auto" = true)))
);
